                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        f"[bold]Estimated ARV:[/bold] ${best.estimated_arv:,.0f}\n"
